/**
 * Benchmark priors — the ONE reader over the enso-bench scored corpus.
 *
 * WHERE THE NUMBERS COME FROM (and why): the corpus is a checked-in fixture
 * (`benchmarks.data.json`, regenerated by `scripts/sync-benchmarks.mjs` from
 * hanzoai/enso-bench `priors/leaderboard.json` + `harness/arms.py`), imported at
 * BUILD TIME. It is a versioned artefact, not live state — it changes when a bench
 * run lands, not per request — so an endpoint would buy nothing and cost a loading
 * state, a failure mode, and a fabrication risk on every page view. Build-time
 * import makes the leaderboard render instantly, offline, and typed.
 *
 * NOTHING HERE IS INVENTED. Every score keeps the `source` string the corpus carries
 * (`hanzo-measured` = our own harness through api.hanzo.ai; `do-catalog`,
 * `fugu-report`, and the named public leaderboards = provider/third-party context).
 * A model with no published score has NO score — callers render an em-dash, never a
 * zero, never a guess.
 *
 * THE JOIN. The corpus keys models by many spellings (`gpt-5.2`, `/gpt-5.2`,
 * `openai-gpt-5.2`), while the live gateway catalog uses its own ids.
 * `normalizeModelKey` folds both into one key so a live catalog row finds its prior;
 * the arms.py alias pairs cover the cases spelling alone cannot bridge.
 */
import data from './benchmarks.data.json'

/** The fixture's wire shape. The JSON literal infers a per-row union of exact score
 *  keys, which is noise here — the corpus is an open set of benchmark ids, so it is
 *  read through one declared shape. */
type Corpus = {
  benchmarks: Record<string, string>
  taskBench: Record<string, string[]>
  models: BenchModel[]
  aliases: [string, string][]
}

const raw = data as unknown as Corpus

/** One published score for one model on one benchmark, with its provenance. */
export type Score = { value: number; source: string }

/** A model's row in the corpus: its vendor and every benchmark it has a score on. */
export type BenchModel = {
  model: string
  vendor: string
  scores: Record<string, Score>
  /** Blended $/MTok as the corpus computed it, or null when it prices no arm. */
  price: number | null
  /** Best single score across the model's benchmarks — the corpus's own summary. */
  intelligence: number | null
}

/** Benchmark id → human label (e.g. `gpqa_diamond` → "GPQA-Diamond"). */
export const BENCHMARKS: Record<string, string> = raw.benchmarks

/** Task kind → the benchmarks that speak to it (the router's own mapping). */
export const TASK_BENCH: Record<string, string[]> = raw.taskBench

/** The benchmark ids, in corpus order (declaration order is the curated order). */
export const BENCHMARK_IDS: string[] = Object.keys(BENCHMARKS)

export const benchmarkLabel = (id: string): string => BENCHMARKS[id] ?? id

// ── Key normalization (the one join implementation) ──────────────────────────

/**
 * Vendor-ORG prefixes that are safe to strip because none of them doubles as the
 * root of a model name. `deepseek`, `kimi`, `minimax`, `qwen`, and `gemma` are
 * deliberately ABSENT: `deepseek-3.2` and `kimi-k2.6` ARE the model names, so
 * stripping would leave a meaningless `3.2`.
 */
const ORG_PREFIX = /^(openai|anthropic|alibaba|nvidia|google|meta|mistral|moonshot|zai|xiaomi)-/

/**
 * Fold one model spelling into the canonical join key.
 *
 * Lowercase → drop a leading slash → keep only the last path segment
 * (`deepseek/deepseek-v4-pro` → `deepseek-v4-pro`) → drop a vendor-org prefix
 * (`openai-gpt-5.2` → `gpt-5.2`) → drop a trailing dated-snapshot suffix
 * (`claude-opus-4-5-20251101` → `claude-opus-4-5`) → write dash-separated version
 * pairs as dotted (`claude-opus-4-5` → `claude-opus-4.5`).
 *
 * Deliberately conservative: spellings that differ by WORD ORDER
 * (`claude-4.6-sonnet` vs `claude-sonnet-4-6`) are left unmerged. An unmatched model
 * shows no score, which is the honest outcome — guessing an identity would attach a
 * real number to the wrong model, the worst failure available here.
 */
export function normalizeModelKey(rawKey: string): string {
  let s = (rawKey ?? '').trim().toLowerCase()
  if (!s) return ''
  s = s.replace(/^\/+/, '')
  const seg = s.split('/')
  s = seg[seg.length - 1] ?? s
  s = s.replace(ORG_PREFIX, '')
  s = s.replace(/-\d{8}$/, '')
  s = s.replace(/-(\d+)-(\d+)(?=$|-)/g, '-$1.$2')
  return s
}

// ── Source provenance (the honest measured-vs-reported binary) ────────────────

/**
 * The two kinds of number in the corpus. `measured` is our own harness through
 * api.hanzo.ai — one common effort setting, complete runs, the figure the router
 * actually gets. `reported` is a vendor's or a third party's leaderboard, measured
 * on someone else's harness at someone else's effort. The corpus carries a fine
 * `source` string on every score; this folds it to the one distinction a reader
 * filters on. Only the literal `hanzo-measured` is ours — everything else, however
 * reputable (Vals AI, Artificial Analysis, a model card), is reported.
 */
export type SourceClass = 'measured' | 'reported'
export const sourceClass = (source: string): SourceClass =>
  source === 'hanzo-measured' ? 'measured' : 'reported'

/**
 * The Enso family — our own orchestrated tiers (enso-flash / enso / enso-ultra),
 * measured on our harness. Badged apart from other measured models because they
 * are the product this surface exists to place honestly among its peers.
 */
export const isEnsoModel = (modelIdOrName: string): boolean =>
  /^enso(-|$)/.test(normalizeModelKey(modelIdOrName))

/** Corpus alias pairs: a gateway model id → its canonical corpus name. */
const ALIASES: Record<string, string> = (() => {
  const m: Record<string, string> = {}
  for (const [modelId, canonical] of raw.aliases) {
    m[normalizeModelKey(modelId)] = normalizeModelKey(canonical)
  }
  return m
})()

// ── The indexed corpus ───────────────────────────────────────────────────────

/**
 * Rank a source for the merge below. When two spellings of the SAME model carry a
 * score on the SAME benchmark, we keep the one measured on our own harness — it is
 * what the router actually gets through our gateway. Otherwise first-seen wins, which
 * is corpus order (already sorted best-first), so the merge is deterministic.
 */
const sourceRank = (s: string): number => (s === 'hanzo-measured' ? 2 : 1)

const MODELS: BenchModel[] = raw.models.map((m) => ({
  model: m.model,
  vendor: m.vendor,
  scores: m.scores ?? {},
  price: typeof m.price === 'number' ? m.price : null,
  intelligence: typeof m.intelligence === 'number' ? m.intelligence : null,
}))

/** normalized key → the merged corpus row for that model. */
const INDEX: Map<string, BenchModel> = (() => {
  const idx = new Map<string, BenchModel>()
  for (const m of MODELS) {
    const key = normalizeModelKey(m.model)
    if (!key) continue
    const prev = idx.get(key)
    if (!prev) {
      idx.set(key, { ...m, scores: { ...m.scores } })
      continue
    }
    // Same model, another spelling: union the benchmarks, best source wins a tie.
    for (const [bench, score] of Object.entries(m.scores)) {
      const have = prev.scores[bench]
      if (!have || sourceRank(score.source) > sourceRank(have.source)) prev.scores[bench] = score
    }
    if (prev.price == null && m.price != null) prev.price = m.price
    if (m.intelligence != null && (prev.intelligence == null || m.intelligence > prev.intelligence)) {
      prev.intelligence = m.intelligence
    }
  }
  return idx
})()

/**
 * The corpus row for a model id/name, or null when the model has no published
 * scores. Tries the id as spelled, then its alias, so both a canonical enso name and
 * a live gateway id resolve.
 */
export function priorFor(modelIdOrName: string): BenchModel | null {
  const key = normalizeModelKey(modelIdOrName)
  if (!key) return null
  return INDEX.get(key) ?? INDEX.get(ALIASES[key] ?? '') ?? null
}

/** One model's score on one benchmark, or null when unpublished. */
export function scoreFor(modelIdOrName: string, benchmark: string): Score | null {
  return priorFor(modelIdOrName)?.scores[benchmark] ?? null
}

/** Every corpus row, as loaded. Callers sort; this preserves corpus order. */
export function allPriors(): BenchModel[] {
  return MODELS
}

/** How many corpus rows carry a score on `benchmark` — drives the empty state. */
export function coverage(benchmark: string): number {
  return MODELS.reduce((n, m) => n + (m.scores[benchmark] ? 1 : 0), 0)
}

// ── Leaderboard ranking ──────────────────────────────────────────────────────

/** A ranked leaderboard entry: the corpus row plus the score it ranked on. */
export type Ranked = BenchModel & { rank: number; score: Score }

/**
 * The corpus ranked by one benchmark, best first. Models WITHOUT a published score
 * on that benchmark are OMITTED, never ranked last with a zero — an absent
 * measurement is not a bad measurement. Ties break by model name so the order is
 * stable across renders.
 */
export function leaderboard(benchmark: string): Ranked[] {
  return MODELS.filter((m) => m.scores[benchmark])
    .map((m) => ({ ...m, score: m.scores[benchmark] as Score }))
    .sort((a, b) => b.score.value - a.score.value || a.model.localeCompare(b.model))
    .map((m, i) => ({ ...m, rank: i + 1 }))
}

/** The distinct vendors present in the corpus, alphabetical — the vendor filter. */
export function vendors(): string[] {
  return Array.from(new Set(MODELS.map((m) => m.vendor))).sort((a, b) => a.localeCompare(b))
}
